ALTER TABLE public.profiles ADD COLUMN language text NOT NULL DEFAULT 'ar', ADD COLUMN country text NOT NULL DEFAULT 'EG', ADD COLUMN currency text NOT NULL DEFAULT 'SAR', ADD COLUMN shipping_name text NOT NULL DEFAULT '', ADD COLUMN shipping_phone text NOT NULL DEFAULT '', ADD COLUMN shipping_address text NOT NULL DEFAULT '';
ALTER TABLE public.publishers ADD COLUMN author_code text NOT NULL DEFAULT ('OB-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)));
CREATE UNIQUE INDEX publishers_author_code_unique ON public.publishers(author_code);
CREATE OR REPLACE FUNCTION public.protect_author_code() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.author_code IS DISTINCT FROM OLD.author_code THEN RAISE EXCEPTION 'Author code cannot change'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_author_code BEFORE UPDATE ON public.publishers FOR EACH ROW EXECUTE FUNCTION public.protect_author_code();
ALTER TABLE public.orders ADD COLUMN payment_state text NOT NULL DEFAULT 'unpaid', ADD COLUMN settlement_currency text NOT NULL DEFAULT 'SAR', ADD COLUMN payment_reference text;
CREATE TABLE public.reader_favorites (user_id uuid NOT NULL, book_id uuid NOT NULL REFERENCES public.books(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,book_id));
GRANT SELECT,INSERT,DELETE ON public.reader_favorites TO authenticated; GRANT ALL ON public.reader_favorites TO service_role;
ALTER TABLE public.reader_favorites ENABLE ROW LEVEL SECURITY;
CREATE POLICY favorites_own ON public.reader_favorites FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.manuscripts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), author_id uuid NOT NULL REFERENCES public.publishers(id), title text NOT NULL, author_name text NOT NULL, synopsis text NOT NULL DEFAULT '', format public.book_format NOT NULL DEFAULT 'both', stage text NOT NULL DEFAULT 'review' CHECK(stage IN ('review','revision','accepted','invoiced','production','ready','published')), review_note text NOT NULL DEFAULT '', final_path text, book_id uuid REFERENCES public.books(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.manuscripts TO authenticated; GRANT ALL ON public.manuscripts TO service_role;
ALTER TABLE public.manuscripts ENABLE ROW LEVEL SECURITY;
CREATE POLICY manuscripts_read ON public.manuscripts FOR SELECT TO authenticated USING(author_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.manuscript_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), manuscript_id uuid NOT NULL REFERENCES public.manuscripts(id), file_path text NOT NULL UNIQUE, file_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.manuscript_versions TO authenticated; GRANT ALL ON public.manuscript_versions TO service_role;
ALTER TABLE public.manuscript_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY versions_read ON public.manuscript_versions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.manuscripts m WHERE m.id=manuscript_id AND (m.author_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE TABLE public.production_invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), manuscript_id uuid NOT NULL UNIQUE REFERENCES public.manuscripts(id), invoice_number text NOT NULL UNIQUE DEFAULT ('INV-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))), currency text NOT NULL DEFAULT 'EGP', amount numeric(14,2) NOT NULL CHECK(amount>0), items jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'unpaid' CHECK(status IN ('unpaid','paid','refunded')), payment_reference text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.production_invoices TO authenticated; GRANT ALL ON public.production_invoices TO service_role;
ALTER TABLE public.production_invoices ENABLE ROW LEVEL SECURITY;
CREATE POLICY invoices_read ON public.production_invoices FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.manuscripts m WHERE m.id=manuscript_id AND (m.author_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE TABLE public.production_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), manuscript_id uuid NOT NULL REFERENCES public.manuscripts(id), actor_id uuid NOT NULL, stage text NOT NULL, note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.production_events TO authenticated; GRANT ALL ON public.production_events TO service_role;
ALTER TABLE public.production_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY events_read ON public.production_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.manuscripts m WHERE m.id=manuscript_id AND (m.author_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE TABLE public.author_earnings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), author_id uuid NOT NULL REFERENCES public.publishers(id), order_item_id uuid NOT NULL UNIQUE REFERENCES public.order_items(id), book_title text NOT NULL, format text NOT NULL CHECK(format IN ('digital','physical')), quantity integer NOT NULL, gross numeric(14,2) NOT NULL, share numeric(4,2) NOT NULL, amount numeric(14,2) NOT NULL, currency text NOT NULL, reversed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.author_earnings TO authenticated; GRANT ALL ON public.author_earnings TO service_role;
ALTER TABLE public.author_earnings ENABLE ROW LEVEL SECURITY;
CREATE POLICY earnings_read ON public.author_earnings FOR SELECT TO authenticated USING(author_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.author_payouts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), author_id uuid NOT NULL REFERENCES public.publishers(id), amount numeric(14,2) NOT NULL CHECK(amount>0), currency text NOT NULL, status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','paid','rejected')), transfer_details text NOT NULL, reference text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.author_payouts TO authenticated; GRANT ALL ON public.author_payouts TO service_role;
ALTER TABLE public.author_payouts ENABLE ROW LEVEL SECURITY;
CREATE POLICY payouts_read ON public.author_payouts FOR SELECT TO authenticated USING(author_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.submit_manuscript(_title text,_author_name text,_synopsis text,_format public.book_format,_path text,_filename text,_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE mid uuid; m public.manuscripts; BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.publishers WHERE id=auth.uid()) THEN RAISE EXCEPTION 'Author account required'; END IF; IF length(trim(_title))=0 OR length(trim(_author_name))=0 OR length(trim(_synopsis))=0 OR _path NOT LIKE auth.uid()::text||'/%' OR lower(_path) !~ '\.(doc|docx)$' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='author-documents' AND name=_path) THEN RAISE EXCEPTION 'Valid Word manuscript required'; END IF; IF _id IS NULL THEN INSERT INTO public.manuscripts(author_id,title,author_name,synopsis,format) VALUES(auth.uid(),trim(_title),trim(_author_name),_synopsis,_format) RETURNING id INTO mid; ELSE SELECT * INTO m FROM public.manuscripts WHERE id=_id FOR UPDATE; IF NOT FOUND OR m.author_id<>auth.uid() OR m.stage<>'revision' THEN RAISE EXCEPTION 'Revision not permitted'; END IF; mid:=_id; UPDATE public.manuscripts SET stage='review',updated_at=now() WHERE id=mid; END IF; INSERT INTO public.manuscript_versions(manuscript_id,file_path,file_name) VALUES(mid,_path,_filename); INSERT INTO public.production_events(manuscript_id,actor_id,stage,note) VALUES(mid,auth.uid(),'review','Word manuscript submitted'); RETURN mid; END $$;
REVOKE ALL ON FUNCTION public.submit_manuscript(text,text,text,public.book_format,text,text,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.submit_manuscript(text,text,text,public.book_format,text,text,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.manage_manuscript(_id uuid,_action text,_data jsonb DEFAULT '{}') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.manuscripts; total numeric; dest text; fpath text; bid uuid; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin required'; END IF; SELECT * INTO m FROM public.manuscripts WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Project missing'; END IF; dest:=m.stage; IF _action IN ('accepted','revision') THEN IF m.stage NOT IN ('review','revision','accepted') THEN RAISE EXCEPTION 'Invalid review stage'; END IF; IF _action='revision' AND length(trim(coalesce(_data->>'note','')))=0 THEN RAISE EXCEPTION 'Revision note required'; END IF; dest:=_action; UPDATE public.manuscripts SET review_note=coalesce(_data->>'note','') WHERE id=_id;
ELSIF _action='invoice' THEN IF m.stage<>'accepted' THEN RAISE EXCEPTION 'Accept manuscript first'; END IF; IF jsonb_typeof(_data->'items')<>'array' OR jsonb_array_length(_data->'items')=0 THEN RAISE EXCEPTION 'Invoice items required'; END IF; IF EXISTS(SELECT 1 FROM jsonb_array_elements(_data->'items') i WHERE coalesce(i->>'label','')='' OR coalesce((i->>'amount')::numeric,0)<=0) THEN RAISE EXCEPTION 'Invalid invoice item'; END IF; SELECT sum((i->>'amount')::numeric) INTO total FROM jsonb_array_elements(_data->'items') i; IF coalesce(_data->>'currency','') NOT IN ('EGP','USD','EUR','GBP','SAR','AED') THEN RAISE EXCEPTION 'Invalid currency'; END IF; INSERT INTO public.production_invoices(manuscript_id,currency,amount,items) VALUES(_id,_data->>'currency',total,_data->'items'); dest:='invoiced';
ELSIF _action='production' THEN IF m.stage<>'invoiced' OR NOT EXISTS(SELECT 1 FROM public.production_invoices WHERE manuscript_id=_id AND status='paid' AND payment_reference IS NOT NULL) THEN RAISE EXCEPTION 'Verified invoice payment required'; END IF; dest:='production';
ELSIF _action='ready' THEN fpath:=_data->>'path'; IF m.stage<>'production' OR fpath NOT LIKE m.author_id::text||'/%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='author-documents' AND name=fpath) THEN RAISE EXCEPTION 'Production and final file required'; END IF; UPDATE public.manuscripts SET final_path=fpath WHERE id=_id; dest:='ready';
ELSIF _action='published' THEN bid:=(_data->>'book_id')::uuid; IF m.stage<>'ready' OR NOT EXISTS(SELECT 1 FROM public.books WHERE id=bid AND publisher_id=m.author_id AND status='approved') THEN RAISE EXCEPTION 'Approved author-linked book required'; END IF; UPDATE public.manuscripts SET book_id=bid WHERE id=_id; dest:='published';
ELSE RAISE EXCEPTION 'Unknown action'; END IF; UPDATE public.manuscripts SET stage=dest,updated_at=now() WHERE id=_id; INSERT INTO public.production_events(manuscript_id,actor_id,stage,note) VALUES(_id,auth.uid(),dest,coalesce(_data->>'note','')); END $$;
REVOKE ALL ON FUNCTION public.manage_manuscript(uuid,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.manage_manuscript(uuid,text,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.is_payout_day(_date date) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT extract(day FROM _date)=30 OR (extract(month FROM _date)=2 AND extract(month FROM _date+1)=3) $$;
CREATE OR REPLACE FUNCTION public.request_author_payout(_currency text,_details text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE available numeric; pid uuid; BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.publishers WHERE id=auth.uid()) THEN RAISE EXCEPTION 'Author required'; END IF; IF NOT public.is_payout_day((now() AT TIME ZONE 'Africa/Cairo')::date) THEN RAISE EXCEPTION 'Withdrawals open on day 30 and the last day of February'; END IF; IF length(trim(_details))<5 THEN RAISE EXCEPTION 'Transfer details required'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); SELECT coalesce(sum(amount),0) INTO available FROM public.author_earnings WHERE author_id=auth.uid() AND currency=_currency AND NOT reversed; available:=available-coalesce((SELECT sum(amount) FROM public.author_payouts WHERE author_id=auth.uid() AND currency=_currency AND status IN ('requested','paid')),0); IF available<=0 THEN RAISE EXCEPTION 'No available balance'; END IF; INSERT INTO public.author_payouts(author_id,amount,currency,transfer_details) VALUES(auth.uid(),available,_currency,trim(_details)) RETURNING id INTO pid; RETURN pid; END $$;
REVOKE ALL ON FUNCTION public.request_author_payout(text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.request_author_payout(text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.review_author_payout(_id uuid,_status text,_reference text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin required'; END IF; IF _status NOT IN ('paid','rejected') OR length(trim(_reference))=0 THEN RAISE EXCEPTION 'Transfer reference or rejection reason required'; END IF; UPDATE public.author_payouts SET status=_status,reference=_reference WHERE id=_id AND status='requested'; IF NOT FOUND THEN RAISE EXCEPTION 'Request already reviewed'; END IF; END $$;
REVOKE ALL ON FUNCTION public.review_author_payout(uuid,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.review_author_payout(uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.record_author_earnings() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.payment_state='paid' AND NEW.payment_reference IS NOT NULL AND OLD.payment_state<>'paid' THEN INSERT INTO public.author_earnings(author_id,order_item_id,book_title,format,quantity,gross,share,amount,currency) SELECT b.publisher_id,i.id,b.title,i.format,i.quantity,i.unit_price*i.quantity,CASE WHEN i.format='digital' THEN 0.70 ELSE 0.30 END,round(i.unit_price*i.quantity*(CASE WHEN i.format='digital' THEN 0.70 ELSE 0.30 END),2),NEW.settlement_currency FROM public.order_items i JOIN public.books b ON b.id=i.book_id WHERE i.order_id=NEW.id AND b.publisher_id IS NOT NULL ON CONFLICT(order_item_id) DO UPDATE SET reversed=false; ELSIF NEW.payment_state IN ('refunded','cancelled') THEN UPDATE public.author_earnings SET reversed=true WHERE order_item_id IN(SELECT id FROM public.order_items WHERE order_id=NEW.id); END IF; RETURN NEW; END $$;
CREATE TRIGGER record_author_earnings AFTER UPDATE OF payment_state ON public.orders FOR EACH ROW EXECUTE FUNCTION public.record_author_earnings();
CREATE POLICY author_documents_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='author-documents' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));
CREATE POLICY author_documents_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='author-documents' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));
COMMENT ON COLUMN public.orders.payment_state IS 'Only trusted provider reconciliation may confirm payment; recorded orders default unpaid.';
COMMENT ON TABLE public.author_earnings IS 'Royalties exclude shipping, retain sale-time shares and reverse on full refund/cancellation; no payout from unpaid orders.';